#!/bin/sh
# Nevela: the Laravel app create-nevela makes, without the dashboard. The skeleton,
# Sanctum and the nevela/laravel package from this repository, then the products API
# generated by Nevela from one line of fields. Nothing in it is written by hand.
set -eu
cd /app

composer config repositories.nevela path /nevela-laravel
composer require --no-update 'laravel/sanctum:^4.0' 'nevela/laravel:@dev'
composer install --no-dev --no-scripts --no-interaction --no-progress --prefer-dist

cp .env.example .env
php artisan key:generate --force
php artisan package:discover
php artisan vendor:publish --tag=sanctum-migrations

php artisan nevela:resource Product --fields="name:string, sku:string!, description:text?, price:money, stock:int, active:boolean"
